'use client'

import { useEffect, useState, useRef } from 'react'
import { useRouter } from 'next/navigation'
import { useAuth } from '@/context/AuthContext'
import { useOrders } from '@/hooks/useOrders'
import Breadcrumb from '@/app/components/Common/Breadcrumb'
import Loader from '@/app/components/Common/Loader'
import { Icon } from '@iconify/react/dist/iconify.js'
import Link from 'next/link'

export default function OrdersPage() {
    const router = useRouter()
    const { isAuthenticated, isLoading } = useAuth()
    const { orders, loading, totalPages, totalOrders, fetchSellerOrders } = useOrders()
    const hasFetchedOrders = useRef(false)
    const [currentPage, setCurrentPage] = useState(1)

    useEffect(() => {
        if (isLoading) return

        if (!isAuthenticated) {
            router.push('/')
            return
        }

        if (!hasFetchedOrders.current) {
            fetchSellerOrders(currentPage, 10)
            hasFetchedOrders.current = true
        }
    }, [isAuthenticated, isLoading, router])

    useEffect(() => {
        if (hasFetchedOrders.current) {
            fetchSellerOrders(currentPage, 10)
        }
    }, [currentPage])

    const handlePageChange = (newPage: number) => {
        setCurrentPage(newPage)
    }

    const getStatusColor = (status: string) => {
        switch (status.toLowerCase()) {
            case 'confirmed':
            case 'delivered':
                return 'bg-green-50 text-green-700 border-green-200'
            case 'pending':
                return 'bg-yellow-50 text-yellow-700 border-yellow-200'
            case 'shipped':
            case 'processing':
                return 'bg-blue-50 text-blue-700 border-blue-200'
            case 'cancelled':
            case 'rejected':
                return 'bg-red-50 text-red-700 border-red-200'
            default:
                return 'bg-gray-50 text-gray-700 border-gray-200'
        }
    }

    const getPaymentStatusColor = (status: string) => {
        switch (status.toLowerCase()) {
            case 'completed':
            case 'paid':
                return 'bg-green-50 text-green-700 border-green-200'
            case 'pending':
                return 'bg-yellow-50 text-yellow-700 border-yellow-200'
            case 'failed':
                return 'bg-red-50 text-red-700 border-red-200'
            default:
                return 'bg-gray-50 text-gray-700 border-gray-200'
        }
    }

    if (isLoading) {
        return (
            <div className="flex justify-center items-center min-h-screen">
                <Loader />
            </div>
        )
    }

    if (!isAuthenticated) {
        return null
    }

    return (
        <>
            <Breadcrumb pageName="Orders" />
            <section className="bg-gradient-to-br from-blue-50 to-purple-50 pb-10">
                <div className="container mx-auto max-w-7xl px-4">
                    <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
                        <div className="mb-8">
                            <div className="flex justify-between items-start mb-4">
                                <div>
                                    <h1 className="text-3xl font-bold bg-gradient-to-r from-gray-900 to-gray-700 bg-clip-text text-transparent mb-2">
                                        Orders
                                    </h1>
                                    <div className="flex items-center gap-4">
                                        <p className="text-gray-600 flex items-center gap-2">
                                            <Icon icon="mdi:shopping" width={20} height={20} />
                                            <span>Manage your customer orders</span>
                                        </p>
                                        <span className="px-3 py-1 bg-primary/10 text-primary rounded-full text-sm font-semibold">
                                            {totalOrders} total
                                        </span>
                                    </div>
                                </div>
                                <Link
                                    href="/products"
                                    className="px-4 py-2 bg-gradient-to-r from-primary to-purple-600 text-white rounded-lg hover:shadow-lg transition-all flex items-center gap-2 font-semibold">
                                    <Icon icon="mdi:arrow-left" width={20} height={20} />
                                    Back to Products
                                </Link>
                            </div>
                        </div>

                        {loading && !orders.length ? (
                            <div className="flex justify-center items-center py-20">
                                <Loader />
                            </div>
                        ) : orders.length === 0 ? (
                            <div className="text-center py-20">
                                <div className="mb-4">
                                    <Icon icon="mdi:shopping-outline" className="mx-auto text-gray-300" width={80} height={80} />
                                </div>
                                <h3 className="text-xl font-semibold text-gray-700 mb-2">No Orders Found</h3>
                                <p className="text-gray-500">You haven't received any orders yet.</p>
                            </div>
                        ) : (
                            <>
                                <div className="overflow-x-auto rounded-xl border border-gray-200">
                                    <table className="w-full">
                                        <thead className="bg-gradient-to-r from-gray-50 to-gray-100">
                                            <tr>
                                                <th className="px-6 py-4 text-left">
                                                    <div className="flex items-center gap-2">
                                                        <Icon icon="mdi:package-variant" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Order ID</span>
                                                    </div>
                                                </th>
                                                <th className="px-6 py-4 text-left">
                                                    <div className="flex items-center gap-2">
                                                        <Icon icon="mdi:account" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Customer</span>
                                                    </div>
                                                </th>
                                                <th className="px-6 py-4 text-left">
                                                    <div className="flex items-center gap-2">
                                                        <Icon icon="mdi:cart" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Items</span>
                                                    </div>
                                                </th>
                                                <th className="px-6 py-4 text-left">
                                                    <div className="flex items-center gap-2">
                                                        <Icon icon="mdi:currency-inr" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Total</span>
                                                    </div>
                                                </th>
                                                <th className="px-6 py-4 text-left">
                                                    <div className="flex items-center gap-2">
                                                        <Icon icon="mdi:credit-card" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Payment Method</span>
                                                    </div>
                                                </th>
                                                <th className="px-6 py-4 text-left">
                                                    <div className="flex items-center gap-2">
                                                        <Icon icon="mdi:credit-card" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Payment Status</span>
                                                    </div>
                                                </th>
                                                <th className="px-6 py-4 text-left">
                                                    <div className="flex items-center gap-2">
                                                        <Icon icon="mdi:truck-delivery" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Status</span>
                                                    </div>
                                                </th>
                                                <th className="px-6 py-4 text-left">
                                                    <div className="flex items-center gap-2">
                                                        <Icon icon="mdi:calendar" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Date</span>
                                                    </div>
                                                </th>
                                                <th className="px-6 py-4 text-center">
                                                    <div className="flex items-center justify-center gap-2">
                                                        <Icon icon="mdi:cog" width={18} height={18} className="text-primary" />
                                                        <span className="text-sm font-semibold text-gray-700">Actions</span>
                                                    </div>
                                                </th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-200 bg-white">
                                            {orders.map((order: any) => (
                                                <tr key={order._id} className="hover:bg-gradient-to-r hover:from-blue-50/30 hover:to-purple-50/30 transition-all duration-200">
                                                    <td className="px-6 py-4">
                                                        <span className="font-semibold text-primary">{order.orderId}</span>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div>
                                                            <p className="font-medium text-gray-900">{order.deliveryAddress?.name || 'N/A'}</p>
                                                            <p className="text-xs text-gray-500">{order.userEmail}</p>
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <span className="inline-flex items-center gap-1 px-2 py-1 bg-blue-50 text-blue-700 rounded-lg text-sm font-medium">
                                                            <Icon icon="mdi:package-variant" width={16} height={16} />
                                                            {order.items?.length || 0} item(s)
                                                        </span>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <p className="text-lg font-bold text-primary">₹{Number(order.grandTotal || 0).toLocaleString('en-IN')}</p>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="space-y-1">
                                                            <p className="text-xs text-gray-500 capitalize">{order.paymentType}</p>
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="space-y-1">
                                                            <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-lg text-xs font-semibold border ${getPaymentStatusColor(order.paymentStatus)}`}>
                                                                <Icon icon={order.paymentStatus === 'completed' ? 'mdi:check-circle' : 'mdi:clock-outline'} width={14} height={14} />
                                                                {order.paymentStatus}
                                                            </span>
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold border ${getStatusColor(order.orderStatus)}`}>
                                                            <Icon icon="mdi:truck-delivery" width={14} height={14} />
                                                            {order.orderStatus}
                                                        </span>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <p className="text-sm text-gray-600">
                                                            {new Date(order.createdAt).toLocaleDateString('en-IN', {
                                                                day: '2-digit',
                                                                month: 'short',
                                                                year: 'numeric'
                                                            })}
                                                        </p>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center justify-center">
                                                            <Link
                                                                href={`/orders/${order.orderId}`}
                                                                className="group relative p-2.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-all border border-transparent hover:border-blue-200 hover:shadow-sm"
                                                                title="View Order">
                                                                <Icon icon="mdi:eye" width={20} height={20} />
                                                                <span className="absolute -top-8 left-1/2 -translate-x-1/2 px-2 py-1 bg-gray-800 text-white text-xs rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-10">
                                                                    View Details
                                                                </span>
                                                            </Link>
                                                        </div>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>

                                {totalPages > 1 && (
                                    <div className="mt-8">
                                        <div className="flex justify-between items-center">
                                            <div className="text-sm text-gray-600">
                                                Showing {orders.length} of {totalOrders} results
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <button
                                                    onClick={() => handlePageChange(currentPage - 1)}
                                                    disabled={currentPage === 1}
                                                    className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition flex items-center gap-2 font-medium">
                                                    <Icon icon="mdi:chevron-left" width={20} height={20} />
                                                    Previous
                                                </button>
                                                <div className="flex gap-2">
                                                    {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                                                        <button
                                                            key={page}
                                                            onClick={() => handlePageChange(page)}
                                                            className={`px-4 py-2 rounded-lg font-medium transition ${currentPage === page
                                                                ? 'bg-primary text-white shadow-md'
                                                                : 'border border-gray-300 hover:bg-gray-50'
                                                                }`}>
                                                            {page}
                                                        </button>
                                                    ))}
                                                </div>
                                                <button
                                                    onClick={() => handlePageChange(currentPage + 1)}
                                                    disabled={currentPage === totalPages}
                                                    className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition flex items-center gap-2 font-medium">
                                                    Next
                                                    <Icon icon="mdi:chevron-right" width={20} height={20} />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </section>
        </>
    )
}
